// a dot grid revealed from the centre
vec4 shade(vec2 uv) {
  vec2 cells = vec2(uParams.x, uParams.x * uSize.y / uSize.x);
  vec2 f = fract(uv * cells) - 0.5;
  float d = length(f), aa = fwidth(d) * 1.2;
  float dots = 1.0 - smoothstep(uParams.y - aa, uParams.y + aa, d);
  vec2 p = (uv - 0.5) * vec2(uSize.x / uSize.y, 1.0);
  float reveal = 1.0 - smoothstep(uParams.z - uParams.w, uParams.z, length(p));
  return vec4(uColorA.rgb, uColorA.a * dots * reveal);
}

