// squash on contact, stretch with speed, the volume kept
if (t >= 3) return value;
if (t < 0.5) { const u = t / 0.5, s = 1 + 0.3 * u * u; return [1 / Math.sqrt(s), s]; }
const u = ((t - 0.5) % 0.5) / 0.5, v = Math.abs(1 - 2 * u);
const c = Math.exp(-Math.pow(Math.min(u, 1 - u) / 0.09, 2));
const sy = (1 + 0.22 * v) * (1 - 0.45 * c);
return [1 / Math.sqrt(sy), sy];

