// domain warping (fbm of fbm), in the colours of the film
float hash(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }
float noise(vec2 p) {
  vec2 i = floor(p), f = fract(p), u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}
float fbm(vec2 p) {
  float s = 0.0, a = 0.5;
  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);
  for (int i = 0; i < 6; i++) { s += a * noise(p); p = m * p; a *= 0.5; }
  return s;
}
vec4 shade(vec2 uv) {
  vec2 p = (uv - 0.5) * vec2(uSize.x / uSize.y, 1.0) * 2.6;
  float t = (uTime + uParams.y) * uParams.x;
  vec2 q = vec2(fbm(p + vec2(0.0, t * 0.35)), fbm(p + vec2(5.2, 1.3) - t * 0.25));
  vec2 r = vec2(fbm(p + 4.0 * q + vec2(1.7, 9.2) + t * 0.2), fbm(p + 4.0 * q + vec2(8.3, 2.8) - t * 0.15));
  float f = fbm(p + 4.0 * r);
  vec3 ink = vec3(0.035, 0.047, 0.059), deep = vec3(0.043, 0.227, 0.208);
  vec3 teal = vec3(0.18, 0.77, 0.71), blue = vec3(0.486, 0.718, 1.0), amber = vec3(0.957, 0.722, 0.376);
  vec3 c = mix(ink, deep, smoothstep(0.15, 0.6, f));
  c = mix(c, teal, smoothstep(0.35, 0.95, length(q) * f * 1.5));
  c = mix(c, blue, smoothstep(0.55, 1.0, r.x * f * 1.4) * 0.7);
  c = mix(c, amber, smoothstep(0.82, 1.0, q.y * f * 2.2) * 0.5);
  c += vec3(0.9) * pow(smoothstep(0.62, 1.0, f), 3.0) * 0.55;
  c = mix(c, c * 1.9 + teal * 0.3, uParams.z);
  return vec4(c, 1.0);
}

